local CattleRancher = {}
local PRODUCTS = {
    dairy_cow = { name = "Mlečna krava", cowCost = 1, fodderCost = 2, waterCost = 1, time = 4, cost = 40, yield = 50, happiness = 1, description = "Mlečna krava za proizvodnjo mleka." },
    beef_cow = { name = "Goveja krava", cowCost = 1, fodderCost = 2, waterCost = 1, time = 5, cost = 55, yield = 60, prestige = 1, description = "Goveja krava za meso." },
    ox_team = { name = "Volovska ekipa", cowCost = 2, fodderCost = 3, waterCost = 1, time = 7, cost = 130, yield = 75, prestige = 3, happiness = 1, description = "Volovska ekipa za vleko." },
    silver_horned_cow = { name = "Srebrnoroga krava", cowCost = 1, silverCost = 1, fodderCost = 2, waterCost = 1, time = 9, cost = 300, yield = 85, prestige = 7, happiness = 2, description = "Srebrnoroga krava za plemiče." },
    silver_bell_dairy = { name = "Srebrno zvončna mlečnica", cowCost = 2, silverCost = 1, fodderCost = 3, waterCost = 2, time = 12, cost = 620, yield = 92, prestige = 14, happiness = 3, description = "Mlečna krava s srebrnim zvonom za visoke plemiče." },
    royal_grand_herd = { name = "Kraljevski veliki čreda", cowCost = 4, goldCost = 1, silverCost = 1, jewelCost = 1, fodderCost = 5, waterCost = 2, time = 18, cost = 1800, yield = 100, prestige = 38, happiness = 8, description = "Velika kraljevska čreda z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Živinorejska postaja", cost = { gold = 250, wood = 130, stone = 200 }, upkeep = 6, qualityBonus = 5 },
    cattle_ranch = { name = "Goveja farma", cost = { gold = 900, wood = 250, stone = 400, fodder = 10 }, upkeep = 22, qualityBonus = 18 },
    dairy_barn = { name = "Mlečna staja", cost = { gold = 2200, wood = 350, stone = 600, silver = 25, water = 10 }, upkeep = 55, qualityBonus = 30 },
    royal_cattle_atelier = { name = "Kraljevski atelje govedine", cost = { gold = 9000, wood = 600, stone = 1000, gold = 60, jewel = 20 }, upkeep = 180, qualityBonus = 55, prestigeBonus = 40 },
}
CattleRancher.cowStock = 22; CattleRancher.fodderStock = 24; CattleRancher.waterStock = 18; CattleRancher.silverStock = 8; CattleRancher.goldStock = 6; CattleRancher.jewelStock = 6
CattleRancher.productStock = {}; CattleRancher.buildings = {}; CattleRancher.maker = nil; CattleRancher.activeMaking = {}; CattleRancher.totalProducts = 0; CattleRancher.dayTimer = 0
function CattleRancher.init() CattleRancher.cowStock=22; CattleRancher.fodderStock=24; CattleRancher.waterStock=18; CattleRancher.silverStock=8; CattleRancher.goldStock=6; CattleRancher.jewelStock=6; CattleRancher.productStock={}; CattleRancher.buildings={}; CattleRancher.maker=nil; CattleRancher.activeMaking={}; CattleRancher.totalProducts=0; CattleRancher.dayTimer=0; print("[CattleRancher] Royal Cattle Rancher System initialized (6 products, 4 buildings)") end
function CattleRancher.hireMaker(n,s) s=s or math.random(45,85); local c=500+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CattleRancher.maker={name=n or ("Živinorec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Živinorec najet: %s (spretnost: %d)",CattleRancher.maker.name,s),"success") end; return true end
function CattleRancher.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CattleRancher.build(id) local ok,e=CattleRancher.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CattleRancher.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CattleRancher.getQualityBonus() local b=0; for _,bd in ipairs(CattleRancher.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CattleRancher.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.cowCost and CattleRancher.cowStock<(d.cowCost or 0) then return false,"Premalo krav" end; if d.fodderCost and CattleRancher.fodderStock<(d.fodderCost or 0) then return false,"Premalo krme" end; if d.waterCost and CattleRancher.waterStock<(d.waterCost or 0) then return false,"Premalo vode" end; if d.silverCost and CattleRancher.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CattleRancher.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CattleRancher.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #CattleRancher.buildings==0 then return false,"Potrebna delavnica" end; if not CattleRancher.maker then return false,"Potreben živinorec" end; return true end
function CattleRancher.make(pt,qty) qty=qty or 5; local ok,e=CattleRancher.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.cowCost then CattleRancher.cowStock=CattleRancher.cowStock-d.cowCost*qty end; if d.fodderCost then CattleRancher.fodderStock=CattleRancher.fodderStock-d.fodderCost*qty end; if d.waterCost then CattleRancher.waterStock=CattleRancher.waterStock-d.waterCost*qty end; if d.silverCost then CattleRancher.silverStock=CattleRancher.silverStock-d.silverCost*qty end; if d.goldCost then CattleRancher.goldStock=CattleRancher.goldStock-d.goldCost*qty end; if d.jewelCost then CattleRancher.jewelStock=CattleRancher.jewelStock-d.jewelCost*qty end; local t=d.time; if CattleRancher.maker then t=math.max(1,t-math.floor(CattleRancher.maker.skill/12)) end; table.insert(CattleRancher.activeMaking,{id="cattle_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,yield=d.yield or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CattleRancher.completeMaking(m) local q=1.0+(CattleRancher.getQualityBonus()/100); if CattleRancher.maker then q=q+(CattleRancher.maker.skill/180) end; q=math.min(2.0,q); CattleRancher.productStock[m.productType]=(CattleRancher.productStock[m.productType] or 0)+m.quantity; CattleRancher.totalProducts=CattleRancher.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CattleRancher.maker then CattleRancher.maker.itemsMade=CattleRancher.maker.itemsMade+m.quantity; if math.random()<0.20 then CattleRancher.maker.skill=math.min(100,CattleRancher.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Čreda vzrejena: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"cattle.completed",{productName=m.productName,yield=m.yield,happiness=m.happiness}) end end
function CattleRancher.update(dt) if not _G.state then return end; CattleRancher.dayTimer=CattleRancher.dayTimer+dt; if CattleRancher.dayTimer>=30 then CattleRancher.dayTimer=0; for i=#CattleRancher.activeMaking,1,-1 do local m=CattleRancher.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CattleRancher.completeMaking(m); table.remove(CattleRancher.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CattleRancher.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CattleRancher.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CattleRancher.getStats() return {cowStock=CattleRancher.cowStock,fodderStock=CattleRancher.fodderStock,waterStock=CattleRancher.waterStock,silverStock=CattleRancher.silverStock,goldStock=CattleRancher.goldStock,jewelStock=CattleRancher.jewelStock,productStock=CattleRancher.productStock,numBuildings=#CattleRancher.buildings,hasMaker=CattleRancher.maker~=nil,makerName=CattleRancher.maker and CattleRancher.maker.name or "—",makerSkill=CattleRancher.maker and CattleRancher.maker.skill or 0,activeMaking=#CattleRancher.activeMaking,totalProducts=CattleRancher.totalProducts} end
return CattleRancher
